files.shaders/bg.gdshader:
shader_type canvas_item;
uniform vec4 c1 : source_color = vec4(1.0, 0.24, 0.5, 1.0);
uniform vec4 c2 : source_color = vec4(1.0, 0.42, 0.62, 1.0);
uniform float pattern = 0.0;
uniform vec2 size = vec2(1200.0, 900.0);
uniform float cell = 80.0;
uniform float speed = 1.0;

void fragment() {
	vec2 p = UV * size;
	float t = TIME * 60.0 * speed;
	float v = 0.0;
	if (pattern < 0.5) {
		v = step(0.5, fract((p.x + p.y + t) / (cell * 2.0)));
	} else if (pattern < 1.5) {
		vec2 q = p + vec2(t, t * 0.6);
		vec2 g = fract(q / cell) - 0.5;
		float row = floor(q.y / cell);
		g.x = fract(q.x / cell + 0.5 * mod(row, 2.0)) - 0.5;
		v = 1.0 - smoothstep(0.2, 0.23, length(g));
	} else if (pattern < 2.5) {
		vec2 g = floor((p + vec2(t * 0.5, t * 0.5)) / cell);
		v = mod(g.x + g.y, 2.0);
	} else if (pattern < 3.5) {
		vec2 c = p - size * 0.5;
		float a = atan(c.y, c.x);
		float r = length(c);
		v = step(0.5, fract(a / 6.2831853 * 14.0 + r / 600.0 - TIME * 0.25 * speed));
	} else {
		// night sky with twinkling stars
		vec2 g = floor(p / 6.0);
		float h = fract(sin(dot(g, vec2(12.9898, 78.233))) * 43758.5453);
		float tw = 0.5 + 0.5 * sin(TIME * 2.0 + h * 40.0);
		v = step(0.9975, h) * tw;
		vec3 sky = mix(c1.rgb, c2.rgb, UV.y);
		COLOR = vec4(sky + vec3(v), 1.0);
	}
	if (pattern < 3.5) {
		vec3 col = mix(c1.rgb, c2.rgb, v);
		float vig = 1.0 - 0.3 * pow(length(UV - 0.5) * 1.35, 2.0);
		COLOR = vec4(col * vig, 1.0);
	}
}

files.shaders/wipe.gdshader:
shader_type canvas_item;
uniform float r = 2.0;
uniform vec2 size = vec2(1200.0, 900.0);
uniform vec4 col1 : source_color = vec4(0.16, 0.1, 0.26, 1.0);
uniform vec4 col2 : source_color = vec4(0.55, 0.36, 0.96, 1.0);

void fragment() {
	vec2 c = (UV - 0.5) * size;
	float d = length(c) / length(size * 0.5);
	float a = atan(c.y, c.x);
	float stripes = step(0.5, fract(a / 6.2831853 * 16.0 + TIME * 0.5));
	vec4 fill = mix(col1, col2, stripes * 0.35);
	float edge = smoothstep(r, r + 0.004, d);
	float rim = smoothstep(r - 0.03, r, d) * (1.0 - smoothstep(r, r + 0.03, d));
	COLOR = mix(vec4(0.0), fill, edge);
	COLOR = mix(COLOR, vec4(1.0, 0.82, 0.25, 1.0), rim * step(0.001, r) * step(r, 1.2));
}

files.scripts/bubble.gd:
extends "res://scripts/screen.gd"
## Endless bubble wrap.

var b_back: Dictionary
var bubbles: Array = []
var sheet := Rect2()
var left := 0
var slide := 0.0   # >0 while a new sheet slides in
var popped_session := 0
var r := 36.0
var sheet_col := Color(0.82, 0.93, 1.0)


func setup() -> void:
	b_back = add_back(func(): G.main.go("fidget"))
	bg(Color("2a6fd1"), Color("3279dc"), 2, 70, 0.15)
	G.play_music("chill")


func layout() -> void:
	place_back(b_back)
	make_sheet()


func make_sheet() -> void:
	bubbles.clear()
	sheet = Rect2(40 * U, 150 * U, W - 80 * U, H - 190 * U)
	r = 38.0 * U
	var dx := r * 2.25
	var dy := r * 1.95
	var cols := int((sheet.size.x - r) / dx)
	var rows := int((sheet.size.y - r * 0.6) / dy)
	var ox := sheet.position.x + (sheet.size.x - (cols - 1) * dx - dx * 0.5) * 0.5
	var oy := sheet.position.y + (sheet.size.y - (rows - 1) * dy) * 0.5
	for j in rows:
		for i in cols:
			var p := Vector2(ox + i * dx + (dx * 0.5 if j % 2 == 1 else 0.0), oy + j * dy)
			bubbles.append({p = p, popped = false, k = 0.0, seed = randf() * 10.0})
	left = bubbles.size()
	sheet_col = [Color(0.82, 0.93, 1.0), Color(0.9, 0.86, 1.0), Color(0.86, 1.0, 0.9), Color(1.0, 0.9, 0.86)][randi() % 4]


func pop_at(p: Vector2) -> void:
	if slide > 0.0:
		return
	for b in bubbles:
		if not b.popped and p.distance_to(b.p) < r * 1.05:
			b.popped = true
			b.k = 1.0
			left -= 1
			popped_session += 1
			G.data.bubbles += 1
			G.play("wrap%d" % randi_range(1, 3), randf_range(0.88, 1.18), randf_range(-3.0, 0.0))
			fx.puff(b.p, Color(1, 1, 1, 0.7), 4, 90 * U)
			if left == 0:
				G.play("sparkle")
				fx.text(Vector2(W * 0.5, H * 0.5), "NEW SHEET!", G.YELLOW, 80 * U)
				slide = 1.0
				G.save_game()
			return


func down(p: Vector2, _i: int) -> void:
	pop_at(p)


func drag(p: Vector2, _i: int, _rel: Vector2) -> void:
	pop_at(p)


func update(dt: float) -> void:
	for b in bubbles:
		b.k = maxf(0.0, b.k - dt * 5.0)
	if slide > 0.0:
		var before := slide
		slide -= dt * 1.4
		if before > 0.5 and slide <= 0.5:
			make_sheet()
		if slide <= 0.0:
			slide = 0.0


func back() -> void:
	G.save_game()
	G.main.go("fidget")


func _exit_tree() -> void:
	G.save_game()


func paint() -> void:
	var off := 0.0
	if slide > 0.5:
		off = -(1.0 - slide) * 2.0 * W
	elif slide > 0.0:
		off = slide * 2.0 * W
	var s := Rect2(sheet.position + Vector2(off, 0), sheet.size)
	G.rrect(self, s, 30 * U, Color(sheet_col, 0.92), 6 * U, G.NAVY, 16 * U)
	for b in bubbles:
		var p: Vector2 = b.p + Vector2(off, 0)
		if not b.popped:
			draw_circle(p + Vector2(4, 6) * U, r, Color(0, 0, 0.2, 0.12), true, -1.0, true)
			draw_circle(p, r, Color(1, 1, 1, 0.55), true, -1.0, true)
			draw_arc(p, r, 0, TAU, 32, Color(0.35, 0.55, 0.75, 0.7), 3 * U, true)
			draw_arc(p, r * 0.8, PI * 0.9, PI * 1.45, 10, Color(1, 1, 1, 0.95), 5 * U, true)
			draw_circle(p + Vector2(-r * 0.35, -r * 0.4), r * 0.13, Color.WHITE, true, -1.0, true)
			draw_arc(p, r * 0.72, 0.1, 0.9, 8, Color(0.3, 0.5, 0.7, 0.25), 4 * U, true)
		else:
			var sq: float = 1.0 + b.k * 0.25
			var pts := PackedVector2Array()
			for k in 14:
				var a := TAU * k / 14.0
				var rr := r * (0.78 + 0.16 * sin(a * 3.0 + b.seed) * sin(a * 2.0 + b.seed * 1.7)) * sq
				pts.append(p + Vector2(cos(a), sin(a)) * rr)
			draw_colored_polygon(pts, Color(1, 1, 1, 0.22))
			pts.append(pts[0])
			draw_polyline(pts, Color(0.35, 0.55, 0.75, 0.45), 2.5 * U, true)
			draw_line(p + Vector2(-r * 0.4, -r * 0.1), p + Vector2(r * 0.3, r * 0.2), Color(0.35, 0.55, 0.75, 0.35), 2 * U, true)
	title_text(Vector2(W * 0.5, 70 * U), "BUBBLE WRAP", 66, false)
	G.txt(self, Vector2(W - 40 * U, 120 * U), "POPPED: %d" % int(G.data.bubbles), int(30 * U), G.YELLOW, int(7 * U), G.font_title, HORIZONTAL_ALIGNMENT_RIGHT)

files.scripts/g.gd:
extends Node
## Global helpers: palette, fonts, audio, save data and cartoon drawing primitives.

const NAVY := Color("2a1b3d")
const PINK := Color("ff3d7f")
const YELLOW := Color("ffd23f")
const CYAN := Color("2ec4ff")
const LIME := Color("7cf05a")
const PURPLE := Color("8b5cf6")
const ORANGE := Color("ff8a3d")
const RED := Color("ff4757")
const WHITE := Color("ffffff")
const BLOB := Color("a9aec4")
const BLOB_DARK := Color("7d8299")
const RAINBOW := [Color("ff3d7f"), Color("ff8a3d"), Color("ffd23f"), Color("7cf05a"), Color("2ec4ff"), Color("8b5cf6")]

const SFX := ["bonk", "boom", "boop", "boss", "buzz", "cheer", "click", "coin", "ding", "fanfare", "flip", "giggle",
	"jump", "kick", "levelup", "lose", "nom", "plug", "pop1", "pop2", "pop3", "popit1", "popit2", "puff", "pump",
	"rocket", "scrub", "slurp", "sparkle", "speedup", "splat", "squeak", "squish1", "squish2", "squish3", "swish",
	"tap", "tick", "tock", "whoosh", "win", "wrap1", "wrap2", "wrap3", "wtick", "yawn"]

var font_title: Font
var font_body: Font
var font_bold: Font
var sfx := {}
var music := {}
var players: Array[AudioStreamPlayer] = []
var _pi := 0
var music_player: AudioStreamPlayer
var music_name := ""
var whir: AudioStreamPlayer
var main: Node = null

var data := {
	"best": 0, "won": 0, "rounds": 0, "bubbles": 0, "popits": 0, "spin_best": 0,
	"fireworks": 0, "busters": 0, "sound": true, "music": true, "slime": 0, "boss_wins": 0,
}
const SAVE_PATH := "user://anti_boredom.cfg"

var _sb := StyleBoxFlat.new()


func _ready() -> void:
	font_title = load("res://fonts/title.ttf")
	font_body = load("res://fonts/body.ttf")
	font_bold = load("res://fonts/bold.ttf")
	for n in SFX:
		sfx[n] = load("res://sfx/%s.wav" % n)
	for n in ["blast", "menu", "chill"]:
		var s: AudioStreamOggVorbis = load("res://music/%s.ogg" % n)
		s.loop = true
		music[n] = s
	for i in 14:
		var p := AudioStreamPlayer.new()
		add_child(p)
		players.append(p)
	music_player = AudioStreamPlayer.new()
	music_player.volume_db = -9.0
	add_child(music_player)
	whir = AudioStreamPlayer.new()
	var w: AudioStreamWAV = load("res://sfx/whir.wav")
	w.loop_mode = AudioStreamWAV.LOOP_FORWARD
	w.loop_begin = 0
	w.loop_end = 44100
	whir.stream = w
	whir.volume_db = -60.0
	add_child(whir)
	_sb.anti_aliasing = true
	_sb.corner_detail = 10
	load_game()


# ------------------------------------------------------------------ audio
func play(n: String, pitch := 1.0, vol_db := 0.0) -> void:
	if not data.sound:
		return
	var s = sfx.get(n)
	if s == null:
		return
	var p := players[_pi]
	_pi = (_pi + 1) % players.size()
	p.stream = s
	p.pitch_scale = clampf(pitch, 0.25, 4.0)
	p.volume_db = vol_db
	p.play()


func play_music(n: String, pitch := 1.0) -> void:
	music_player.pitch_scale = pitch
	if music_name == n and music_player.playing:
		return
	music_name = n
	if not data.music:
		music_player.stop()
		return
	music_player.stream = music[n]
	music_player.play()


func set_music_pitch(p: float) -> void:
	music_player.pitch_scale = p


func stop_music() -> void:
	music_name = ""
	music_player.stop()


func toggle_music() -> void:
	data.music = not data.music
	if data.music:
		var n := music_name
		music_name = ""
		if n != "":
			play_music(n, music_player.pitch_scale)
	else:
		music_player.stop()
	save_game()


# ------------------------------------------------------------------ save
func load_game() -> void:
	var cf := ConfigFile.new()
	if cf.load(SAVE_PATH) == OK:
		for k in data.keys():
			data[k] = cf.get_value("save", k, data[k])


func save_game() -> void:
	var cf := ConfigFile.new()
	for k in data.keys():
		cf.set_value("save", k, data[k])
	cf.save(SAVE_PATH)


# ------------------------------------------------------------------ drawing helpers
func circ(ci: CanvasItem, c: Vector2, r: float, col: Color, lw := 5.0, lc := NAVY) -> void:
	if lw > 0.0:
		ci.draw_circle(c, r + lw, lc, true, -1.0, true)
	ci.draw_circle(c, r, col, true, -1.0, true)


func shine(ci: CanvasItem, c: Vector2, r: float, a := 0.55) -> void:
	ci.draw_circle(c + Vector2(-r * 0.36, -r * 0.4), r * 0.2, Color(1, 1, 1, a), true, -1.0, true)
	ci.draw_circle(c + Vector2(-r * 0.12, -r * 0.6), r * 0.08, Color(1, 1, 1, a * 0.8), true, -1.0, true)


func ellipse_pts(c: Vector2, rx: float, ry: float, n := 36, rot := 0.0) -> PackedVector2Array:
	var pts := PackedVector2Array()
	for i in n:
		var a := TAU * i / n
		pts.append(c + Vector2(cos(a) * rx, sin(a) * ry).rotated(rot))
	return pts


func poly(ci: CanvasItem, pts: PackedVector2Array, col: Color, lw := 5.0, lc := NAVY) -> void:
	if pts.size() < 3:
		return
	if lw > 0.0:
		var o := Geometry2D.offset_polygon(pts, lw, Geometry2D.JOIN_ROUND)
		if o.size() > 0 and o[0].size() >= 3:
			ci.draw_colored_polygon(o[0], lc)
	ci.draw_colored_polygon(pts, col)


func ellipse(ci: CanvasItem, c: Vector2, rx: float, ry: float, col: Color, lw := 5.0, rot := 0.0, lc := NAVY) -> void:
	if lw > 0.0:
		ci.draw_colored_polygon(ellipse_pts(c, rx + lw, ry + lw, 40, rot), lc)
	ci.draw_colored_polygon(ellipse_pts(c, rx, ry, 40, rot), col)


func rrect(ci: CanvasItem, r: Rect2, rad: float, col: Color, lw := 5.0, lc := NAVY, shadow := 0.0) -> void:
	_sb.bg_color = col
	_sb.set_corner_radius_all(int(rad))
	_sb.set_border_width_all(int(lw))
	_sb.border_color = lc
	_sb.shadow_size = int(shadow)
	_sb.shadow_offset = Vector2(0, shadow * 0.6)
	_sb.shadow_color = Color(0, 0, 0, 0.28)
	ci.draw_style_box(_sb, r)


func seg(ci: CanvasItem, a: Vector2, b: Vector2, col: Color, w: float, lc := NAVY, ol := 5.0) -> void:
	if ol > 0.0:
		ci.draw_line(a, b, lc, w + ol * 2.0, true)
		ci.draw_circle(a, w * 0.5 + ol, lc, true, -1.0, true)
		ci.draw_circle(b, w * 0.5 + ol, lc, true, -1.0, true)
	ci.draw_line(a, b, col, w, true)
	ci.draw_circle(a, w * 0.5, col, true, -1.0, true)
	ci.draw_circle(b, w * 0.5, col, true, -1.0, true)


func txt(ci: CanvasItem, pos: Vector2, s: String, size: int, col := WHITE, outline := 10, f: Font = null,
		align := HORIZONTAL_ALIGNMENT_CENTER, oc := NAVY, shadow := true) -> void:
	if f == null:
		f = font_title
	size = maxi(size, 6)
	var w := 4000.0
	var x := pos.x - w * 0.5
	if align == HORIZONTAL_ALIGNMENT_LEFT:
		x = pos.x
	elif align == HORIZONTAL_ALIGNMENT_RIGHT:
		x = pos.x - w
	var base := pos.y + (f.get_ascent(size) - f.get_descent(size)) * 0.5
	if f == font_title:
		base += size * 0.08
	if shadow and outline > 0:
		ci.draw_string_outline(f, Vector2(x, base + size * 0.09), s, align, w, size, outline, Color(oc, 0.55))
	if outline > 0:
		ci.draw_string_outline(f, Vector2(x, base), s, align, w, size, outline, oc)
	ci.draw_string(f, Vector2(x, base), s, align, w, size, col)


func mtxt(ci: CanvasItem, center: Vector2, s: String, size: int, width: float, col := NAVY, f: Font = null, outline := 0, oc := NAVY) -> void:
	if f == null:
		f = font_bold
	var sz := f.get_multiline_string_size(s, HORIZONTAL_ALIGNMENT_CENTER, width, size)
	var top := center.y - sz.y * 0.5 + f.get_ascent(size)
	var pos := Vector2(center.x - width * 0.5, top)
	if outline > 0:
		ci.draw_multiline_string_outline(f, pos, s, HORIZONTAL_ALIGNMENT_CENTER, width, size, -1, outline, oc)
	ci.draw_multiline_string(f, pos, s, HORIZONTAL_ALIGNMENT_CENTER, width, size, -1, col)


func text_width(s: String, size: int, f: Font = null) -> float:
	if f == null:
		f = font_title
	return f.get_string_size(s, HORIZONTAL_ALIGNMENT_LEFT, -1, size).x


func star_pts(c: Vector2, r: float, inner := 0.48, n := 5, rot := -PI / 2) -> PackedVector2Array:
	var pts := PackedVector2Array()
	for i in n * 2:
		var rr := r if i % 2 == 0 else r * inner
		var a := rot + PI * i / n
		pts.append(c + Vector2(cos(a), sin(a)) * rr)
	return pts


func heart_pts(c: Vector2, r: float, n := 40) -> PackedVector2Array:
	var pts := PackedVector2Array()
	for i in n:
		var t := TAU * i / n
		var x := 16.0 * pow(sin(t), 3)
		var y := -(13.0 * cos(t) - 5.0 * cos(2 * t) - 2.0 * cos(3 * t) - cos(4 * t))
		pts.append(c + Vector2(x, y) * r / 16.0)
	return pts


func eyes(ci: CanvasItem, c: Vector2, r: float, look := Vector2.ZERO, sleepy := 0.0, spread := 1.0, lid_col := WHITE) -> void:
	## two cartoon eyes centred on c, r = eye radius
	for sx in [-1.0, 1.0]:
		var e: Vector2 = c + Vector2(sx * r * 1.15 * spread, 0)
		circ(ci, e, r, WHITE, r * 0.22)
		var pp: Vector2 = e + look.limit_length(1.0) * r * 0.4 + Vector2(0, r * 0.08)
		ci.draw_circle(pp, r * 0.5, NAVY, true, -1.0, true)
		ci.draw_circle(pp + Vector2(-r * 0.16, -r * 0.18), r * 0.16, WHITE, true, -1.0, true)
		if sleepy > 0.0:
			# eyelid covers the top part of the eye
			var lid := PackedVector2Array()
			var cover := lerpf(-1.0, 0.9, sleepy)
			for i in 21:
				var a := PI + PI * i / 20.0
				lid.append(e + Vector2(cos(a), sin(a)) * (r + 1.0))
			lid.append(e + Vector2(r + 1.0, cover * r))
			lid.append(e + Vector2(-r - 1.0, cover * r))
			ci.draw_colored_polygon(lid, lid_col)
			ci.draw_line(e + Vector2(-r * 1.05, cover * r), e + Vector2(r * 1.05, cover * r), NAVY, r * 0.2, true)


func smile(ci: CanvasItem, c: Vector2, w: float, curve := 1.0, th := 6.0, col := NAVY) -> void:
	var pts := PackedVector2Array()
	for i in 13:
		var f := i / 12.0
		pts.append(c + Vector2((f - 0.5) * w, sin(f * PI) * w * 0.35 * curve))
	ci.draw_polyline(pts, col, th, true)
	ci.draw_circle(pts[0], th * 0.5, col, true, -1.0, true)
	ci.draw_circle(pts[pts.size() - 1], th * 0.5, col, true, -1.0, true)


func buddy(ci: CanvasItem, c: Vector2, r: float, col: Color, t: float, mood := 0, look := Vector2.ZERO) -> void:
	## round "Fun-bot" hero. mood 0 happy, 1 wow, 2 sleepy/sad, 3 dizzy
	var sq := 1.0 + sin(t * 9.0) * 0.03
	ellipse(ci, c + Vector2(0, r * 0.95), r * 0.75, r * 0.16, Color(0, 0, 0, 0.18), 0.0)
	var body := ellipse_pts(c, r * sq, r / sq, 40)
	poly(ci, body, col if mood != 2 else col.lerp(Color("9aa0b5"), 0.7), r * 0.08)
	# antenna
	var tip := c + Vector2(r * 0.25, -r * 1.45) + Vector2(sin(t * 5) * r * 0.08, 0)
	ci.draw_line(c + Vector2(r * 0.1, -r * 0.95), tip, NAVY, r * 0.07, true)
	circ(ci, tip, r * 0.14, YELLOW if mood != 2 else Color("cccccc"), r * 0.05)
	shine(ci, c, r)
	var er := r * 0.27
	var ec := c + Vector2(0, -r * 0.15)
	if mood == 3:
		for sx in [-1.0, 1.0]:
			var e: Vector2 = ec + Vector2(sx * er * 1.2, 0)
			var sp := PackedVector2Array()
			for i in 24:
				var a := i * 0.6 + t * 8.0
				sp.append(e + Vector2(cos(a), sin(a)) * er * (0.2 + i / 30.0))
			ci.draw_polyline(sp, NAVY, r * 0.05, true)
	else:
		eyes(ci, ec, er, look, 0.65 if mood == 2 else 0.0, 1.0, col.lerp(Color("9aa0b5"), 0.7))
	var mc := c + Vector2(0, r * 0.38)
	match mood:
		0:
			smile(ci, mc - Vector2(0, r * 0.06), r * 0.6, 1.0, r * 0.08)
		1:
			ellipse(ci, mc + Vector2(0, r * 0.05), r * 0.16, r * 0.2, Color("b0254f"), r * 0.06)
		2:
			smile(ci, mc + Vector2(0, r * 0.12), r * 0.4, -0.6, r * 0.07)
		3:
			ci.draw_line(mc + Vector2(-r * 0.2, r * 0.05), mc + Vector2(r * 0.2, -r * 0.02), NAVY, r * 0.07, true)
	# cheeks
	if mood != 2:
		ci.draw_circle(c + Vector2(-r * 0.6, r * 0.2), r * 0.12, Color(1, 0.4, 0.5, 0.45), true, -1.0, true)
		ci.draw_circle(c + Vector2(r * 0.6, r * 0.2), r * 0.12, Color(1, 0.4, 0.5, 0.45), true, -1.0, true)


func blob_pts(c: Vector2, r: float, t: float, squash := 1.0, n := 48) -> PackedVector2Array:
	var pts := PackedVector2Array()
	var floor_y := c.y + r * 0.82 * squash
	for i in n:
		var a := TAU * i / n
		var rr := r * (1.0 + 0.05 * sin(3.0 * a + t * 2.2) + 0.035 * sin(5.0 * a - t * 3.1) + 0.02 * sin(9.0 * a + t * 4.0))
		var p := c + Vector2(cos(a) * rr / sqrt(squash), sin(a) * rr * squash)
		if p.y > floor_y:
			p.y = floor_y + (p.y - floor_y) * 0.15
		pts.append(p)
	return pts


func boredom_blob(ci: CanvasItem, c: Vector2, r: float, t: float, mood := 0, splats: Array = [], squash := 1.0) -> void:
	## The Boredom Blob. mood 0 sleepy smug, 1 yawning, 2 shocked, 3 laughing, 4 angry-ish
	ellipse(ci, c + Vector2(0, r * 0.88 * squash), r * 1.05, r * 0.17, Color(0, 0, 0, 0.22), 0.0)
	var pts := blob_pts(c, r, t, squash)
	poly(ci, pts, BLOB, r * 0.05)
	# belly shade
	var inner := PackedVector2Array()
	for p in pts:
		inner.append(c + (p - c) * 0.82 + Vector2(r * 0.06, r * 0.08))
	ci.draw_colored_polygon(inner, Color("b7bcd0"))
	for s in splats:
		var sp: Vector2 = c + Vector2(cos(s.a), sin(s.a)) * r * s.d
		var sr: float = r * s.s
		ci.draw_colored_polygon(splat_pts(sp, sr, s.seed), s.col)
	shine(ci, c + Vector2(-r * 0.1, -r * 0.15), r * 0.9, 0.35)
	var er := r * 0.2
	var ec := c + Vector2(0, -r * 0.25)
	match mood:
		0:
			eyes(ci, ec, er, Vector2(0.3, 0.2), 0.62, 1.1, BLOB)
		1:
			eyes(ci, ec, er, Vector2(0, -0.5), 0.82, 1.1, BLOB)
		2:
			eyes(ci, ec, er * 1.15, Vector2.ZERO, 0.0, 1.1, BLOB)
		3:
			for sx in [-1.0, 1.0]:
				var e: Vector2 = ec + Vector2(sx * er * 1.25, 0)
				var arc := PackedVector2Array()
				for i in 11:
					var a := PI + PI * i / 10.0
					arc.append(e + Vector2(cos(a), sin(a) * 0.8) * er)
				ci.draw_polyline(arc, NAVY, er * 0.3, true)
		4:
			eyes(ci, ec, er, Vector2(0, 0.3), 0.45, 1.1, BLOB)
	var mc := c + Vector2(0, r * 0.22)
	match mood:
		0:
			var m := PackedVector2Array()
			for i in 9:
				var f := i / 8.0
				m.append(mc + Vector2((f - 0.5) * r * 0.5, sin(f * PI) * r * 0.06 + (f - 0.5) * r * 0.08))
			ci.draw_polyline(m, NAVY, r * 0.045, true)
		1:
			var o := 0.5 + 0.5 * sin(t * 1.4)
			ellipse(ci, mc + Vector2(0, r * 0.06), r * 0.17, r * (0.14 + 0.12 * o), Color("5b2140"), r * 0.04)
		2:
			ellipse(ci, mc + Vector2(0, r * 0.05), r * 0.12, r * 0.16, Color("5b2140"), r * 0.04)
		3:
			var m2 := PackedVector2Array()
			for i in 13:
				var a := PI * i / 12.0
				m2.append(mc + Vector2(cos(a) * r * 0.3, sin(a) * r * 0.26))
			poly(ci, m2, Color("5b2140"), r * 0.04)
			ci.draw_colored_polygon(ellipse_pts(mc + Vector2(0, r * 0.17), r * 0.13, r * 0.06), Color("ff7a9c"))
		4:
			smile(ci, mc + Vector2(0, r * 0.08), r * 0.4, -0.5, r * 0.045)


func splat_pts(c: Vector2, r: float, seed := 1.0) -> PackedVector2Array:
	var pts := PackedVector2Array()
	var n := 18
	for i in n:
		var a := TAU * i / n
		var k := 0.75 + 0.35 * sin(a * 3.0 + seed) * sin(a * 5.0 + seed * 2.0) + (0.35 if i % 3 == 0 else 0.0)
		pts.append(c + Vector2(cos(a), sin(a)) * r * k)
	return pts


func speech(ci: CanvasItem, tip: Vector2, center: Vector2, s: String, size := 34, width := 380.0) -> void:
	var f := font_bold
	var sz := f.get_multiline_string_size(s, HORIZONTAL_ALIGNMENT_CENTER, width, size)
	var r := Rect2(center - sz * 0.5 - Vector2(26, 18), sz + Vector2(52, 36))
	var base := r.get_center()
	var tri := PackedVector2Array([base + (tip - base).normalized().orthogonal() * 22, tip, base - (tip - base).normalized().orthogonal() * 22])
	poly(ci, tri, WHITE, 5.0)
	rrect(ci, r, 26, WHITE, 5)
	ci.draw_colored_polygon(PackedVector2Array([tri[0].lerp(base, 0.3), tri[1].lerp(base, 0.12), tri[2].lerp(base, 0.3)]), WHITE)
	mtxt(ci, r.get_center(), s, size, width, NAVY, f)

