## Base for every micro-game. Runner sets W/H/lvl, calls setup(), then step(dt) each frame.

const Parts = preload("res://scripts/parts.gd")

var W := 1200.0
var H := 900.0
var U := 1.0
var lvl := 1
var t := 0.0
var rt := 0.0
var dur := 5.0
var survive := false
var result := 0
var word := "GO!"
var hint := ""
var c1 := Color("ff3d7f")
var c2 := Color("ff6b9a")
var pat := 0
var area := Rect2()
var fx := Parts.new()
var touching := {}


func init(w: float, h: float, level: int) -> void:
	W = w
	H = h
	lvl = level
	U = minf(W, H) / 900.0
	area = Rect2(40 * U, 150 * U, W - 80 * U, H - 270 * U)
	setup()


func setup() -> void:
	pass


func tick(_dt: float) -> void:
	pass


func paint() -> void:
	pass


func down(_p: Vector2, _i: int) -> void:
	pass


func drag(_p: Vector2, _i: int, _rel: Vector2) -> void:
	pass


func up(_p: Vector2, _i: int) -> void:
	pass


## optional bot used by the self-test
func auto(_dt: float) -> void:
	pass


func win(msg := "") -> void:
	if result == 0:
		result = 1
		if msg != "":
			fx.text(area.get_center() - Vector2(0, 60 * U), msg, G.YELLOW, 80 * U)


func lose(msg := "") -> void:
	if result == 0:
		result = -1
		G.play("buzz", 1.0, -3.0)
		if msg != "":
			fx.text(area.get_center() - Vector2(0, 60 * U), msg, Color("ff5d6c"), 70 * U)


func step(dt: float) -> void:
	t += dt
	if result != 0:
		rt += dt
	tick(dt)
	fx.update(dt)
	queue_redraw()


func _draw() -> void:
	paint()
	fx.draw(self)


func rnd_in(margin := 80.0) -> Vector2:
	return Vector2(randf_range(area.position.x + margin * U, area.end.x - margin * U), randf_range(area.position.y + margin * U, area.end.y - margin * U))


func ground(y: float, col := Color("7cd957"), col2 := Color("5bb33f")) -> void:
	draw_rect(Rect2(0, y, W, H - y), col2)
	draw_rect(Rect2(0, y, W, 18 * U), col)
	draw_line(Vector2(0, y), Vector2(W, y), G.NAVY, 6 * U)

