extends RefCounted
## Tiny particle system shared by screens and micro-games.

enum { DOT, CONF, STAR, TEXT, RING, SPARK, PUFF }

var ps: Array = []
var grav := 900.0


func add(p: Vector2, v: Vector2, life: float, col: Color, size: float, kind := DOT, txt := "") -> void:
	ps.append({p = p, v = v, life = life, max = life, col = col, size = size, kind = kind, rot = randf() * TAU,
		vr = randf_range(-8.0, 8.0), txt = txt, g = 1.0})


func burst(p: Vector2, col: Color, n := 16, sp := 420.0, size := 9.0) -> void:
	for i in n:
		var a := randf() * TAU
		add(p, Vector2(cos(a), sin(a)) * sp * randf_range(0.35, 1.0), randf_range(0.4, 0.8), col.lerp(Color.WHITE, randf() * 0.3), size * randf_range(0.6, 1.3))


func confetti(p: Vector2, n := 40, sp := 700.0) -> void:
	for i in n:
		var a := randf_range(-PI * 0.95, -PI * 0.05)
		add(p, Vector2(cos(a), sin(a)) * sp * randf_range(0.4, 1.0), randf_range(1.0, 1.8), G.RAINBOW[randi() % 6], randf_range(9, 15), CONF)


func rain(w: float, n := 80) -> void:
	for i in n:
		add(Vector2(randf() * w, randf_range(-300, -20)), Vector2(randf_range(-60, 60), randf_range(100, 320)), randf_range(2.0, 3.2), G.RAINBOW[randi() % 6], randf_range(9, 15), CONF)


func stars(p: Vector2, n := 6, sp := 300.0, col := Color("ffd23f")) -> void:
	for i in n:
		var a := TAU * i / n + randf() * 0.3
		var q := {}
		add(p, Vector2(cos(a), sin(a)) * sp, 0.7, col, randf_range(14, 22), STAR)
		q = ps[ps.size() - 1]
		q.g = 0.3


func ring(p: Vector2, col: Color, r := 40.0) -> void:
	add(p, Vector2.ZERO, 0.45, col, r, RING)


func text(p: Vector2, s: String, col := Color.WHITE, size := 52.0) -> void:
	add(p, Vector2(0, -160), 0.9, col, size, TEXT, s)
	ps[ps.size() - 1].g = 0.0


func puff(p: Vector2, col := Color(1, 1, 1, 0.8), n := 8, sp := 160.0) -> void:
	for i in n:
		var a := randf() * TAU
		add(p, Vector2(cos(a), sin(a)) * sp * randf_range(0.3, 1.0), randf_range(0.4, 0.7), col, randf_range(14, 26), PUFF)
		ps[ps.size() - 1].g = -0.1


func update(dt: float) -> void:
	var i := ps.size() - 1
	while i >= 0:
		var q: Dictionary = ps[i]
		q.life -= dt
		if q.life <= 0.0:
			ps.remove_at(i)
		else:
			q.v.y += grav * q.g * dt
			if q.kind == CONF:
				q.v *= 1.0 - 1.8 * dt
				q.v.y += 220.0 * dt
			q.p += q.v * dt
			q.rot += q.vr * dt
		i -= 1


func draw(ci: CanvasItem) -> void:
	for q in ps:
		var f: float = q.life / q.max
		var col: Color = q.col
		match q.kind:
			DOT:
				ci.draw_circle(q.p, q.size * (0.4 + 0.6 * f), Color(col, minf(1.0, f * 2.0)), true, -1.0, true)
			CONF:
				var d: Vector2 = Vector2(cos(q.rot), sin(q.rot)) * q.size * 0.5
				var e: Vector2 = Vector2(-d.y, d.x) * 0.45 * absf(sin(q.rot * 1.7))
				ci.draw_colored_polygon(PackedVector2Array([q.p - d - e, q.p + d - e, q.p + d + e, q.p - d + e]), Color(col, minf(1.0, f * 3.0)))
			STAR:
				var s: float = q.size * (0.5 + 0.5 * f)
				G.poly(ci, G.star_pts(q.p, s, 0.45, 5, q.rot), Color(col, minf(1.0, f * 2.0)), 3.0, Color(G.NAVY, minf(1.0, f * 2.0)))
			RING:
				ci.draw_arc(q.p, q.size * (1.0 + (1.0 - f) * 1.6), 0, TAU, 40, Color(col, f), 8.0 * f + 1.0, true)
			TEXT:
				var sc: float = 1.0 + 0.4 * maxf(0.0, (f - 0.8) / 0.2)
				G.txt(ci, q.p, q.txt, int(q.size * sc), Color(col, minf(1.0, f * 3.0)), 9, null, HORIZONTAL_ALIGNMENT_CENTER, Color(G.NAVY, minf(1.0, f * 3.0)), false)
			SPARK:
				ci.draw_line(q.p, q.p - q.v * 0.035, Color(col, f), q.size * f + 1.0, true)
			PUFF:
				ci.draw_circle(q.p, q.size * (1.4 - f * 0.6), Color(col, col.a * f * 0.8), true, -1.0, true)

