extends Node2D
## Base class for every full-screen page: layout size, chunky buttons, touch routing, particles.

const Parts = preload("res://scripts/parts.gd")

var W := 1200.0
var H := 900.0
var U := 1.0
var T := 0.0
var buttons: Array = []
var fx := Parts.new()
var held := {}  # touch index -> button dict
var portrait := false
var arg = null
var canvas: CanvasItem = self


func _ready() -> void:
	_measure()
	get_viewport().size_changed.connect(_on_resize)
	setup()
	layout()


func _on_resize() -> void:
	_measure()
	layout()


func _measure() -> void:
	var s := get_viewport_rect().size
	W = s.x
	H = s.y
	U = minf(W, H) / 900.0
	portrait = H > W * 1.05


# ---- override points
func setup() -> void:
	pass


func layout() -> void:
	pass


func update(_dt: float) -> void:
	pass


func paint() -> void:
	pass


func paint_top() -> void:
	pass


func down(_p: Vector2, _i: int) -> void:
	pass


func drag(_p: Vector2, _i: int, _rel: Vector2) -> void:
	pass


func up(_p: Vector2, _i: int) -> void:
	pass


func back() -> void:
	G.main.go("title")


# ---- loop
func _process(dt: float) -> void:
	dt = minf(dt, 0.05)
	T += dt
	for b in buttons:
		b.press = move_toward(b.press, 1.0 if b.down else 0.0, dt * 12.0)
		b.pop = maxf(0.0, b.pop - dt * 3.0)
	update(dt)
	fx.update(dt)
	queue_redraw()


func _draw() -> void:
	paint()
	for b in buttons:
		if b.visible:
			draw_button(b)
	fx.draw(self)
	paint_top()


func _input(e: InputEvent) -> void:
	if G.main and G.main.busy:
		return
	if e is InputEventScreenTouch:
		var p: Vector2 = e.position
		if e.pressed:
			var hit = button_at(p)
			if hit != null:
				hit.down = true
				held[e.index] = hit
				G.play("tap", 1.0, -6.0)
				return
			down(p, e.index)
		else:
			if held.has(e.index):
				var b = held[e.index]
				held.erase(e.index)
				b.down = false
				if b.visible and b.rect.grow(20).has_point(p):
					b.pop = 1.0
					G.play("click")
					b.cb.call()
				return
			up(p, e.index)
	elif e is InputEventScreenDrag:
		if held.has(e.index):
			return
		drag(e.position, e.index, e.relative)


func button_at(p: Vector2):
	for i in range(buttons.size() - 1, -1, -1):
		var b = buttons[i]
		if b.visible and b.enabled and b.rect.has_point(p):
			return b
	return null


# ---- buttons
func add_button(text: String, col: Color, cb: Callable, size := 46, icon := "") -> Dictionary:
	var b := {text = text, col = col, cb = cb, size = size, rect = Rect2(), down = false, press = 0.0, pop = 0.0,
		visible = true, enabled = true, icon = icon, round = false, sub = ""}
	buttons.append(b)
	return b


func add_back(cb := Callable()) -> Dictionary:
	var b := add_button("", Color("ffffff"), cb if cb.is_valid() else back, 40, "back")
	b.round = true
	return b


func place_back(b: Dictionary) -> void:
	b.rect = Rect2(Vector2(24, 24) * U, Vector2(96, 96) * U)


func draw_button(b: Dictionary) -> void:
	var r: Rect2 = b.rect
	var depth := 12.0 * U
	var sink: float = depth * b.press * 0.75
	var bounce: float = sin(b.pop * PI) * 0.06
	var c := r.get_center()
	var sr := Rect2(c + (r.position - c) * (1.0 + bounce), r.size * (1.0 + bounce))
	var col: Color = b.col if b.enabled else Color("9b9bb0")
	var dark := col.darkened(0.35)
	var rad := sr.size.y * 0.5 if b.round else minf(34.0 * U, sr.size.y * 0.42)
	# 3D base
	G.rrect(canvas, Rect2(sr.position + Vector2(0, depth), sr.size), rad, dark, 6.0 * U, G.NAVY)
	var top := Rect2(sr.position + Vector2(0, sink), sr.size)
	G.rrect(canvas, top, rad, col, 6.0 * U, G.NAVY)
	# gloss
	var gl := Rect2(top.position + Vector2(top.size.x * 0.08, top.size.y * 0.1), Vector2(top.size.x * 0.84, top.size.y * 0.3))
	G.rrect(canvas, gl, gl.size.y * 0.5, Color(1, 1, 1, 0.28), 0.0)
	var tc := top.get_center()
	if b.icon != "":
		draw_icon(b.icon, tc, top.size.y * 0.32, b)
		if b.text != "":
			G.txt(canvas, tc + Vector2(top.size.y * 0.25, 0), b.text, int(b.size * U), Color.WHITE, int(9 * U))
	elif b.sub != "":
		G.txt(canvas, tc - Vector2(0, top.size.y * 0.13), b.text, int(b.size * U), Color.WHITE, int(10 * U))
		G.txt(canvas, tc + Vector2(0, top.size.y * 0.25), b.sub, int(b.size * U * 0.42), Color(1, 1, 1, 0.95), int(6 * U), G.font_bold, HORIZONTAL_ALIGNMENT_CENTER, G.NAVY, false)
	elif "\n" in b.text:
		var ls: PackedStringArray = b.text.split("\n")
		var lh: float = b.size * U * 0.95
		for k in ls.size():
			G.txt(canvas, tc + Vector2(0, (k - (ls.size() - 1) * 0.5) * lh), ls[k], int(b.size * U), Color.WHITE, int(10 * U))
	else:
		G.txt(canvas, tc, b.text, int(b.size * U), Color.WHITE, int(10 * U))


func draw_icon(kind: String, c: Vector2, s: float, b: Dictionary) -> void:
	match kind:
		"back":
			var pts := PackedVector2Array([c + Vector2(-s, 0), c + Vector2(-0.05 * s, -0.85 * s), c + Vector2(-0.05 * s, -0.35 * s),
				c + Vector2(0.9 * s, -0.35 * s), c + Vector2(0.9 * s, 0.35 * s), c + Vector2(-0.05 * s, 0.35 * s), c + Vector2(-0.05 * s, 0.85 * s)])
			G.poly(canvas, pts, G.NAVY, 0.0)
		"pause":
			G.rrect(canvas, Rect2(c + Vector2(-0.6 * s, -0.75 * s), Vector2(0.42 * s, 1.5 * s)), 0.12 * s, G.NAVY, 0)
			G.rrect(canvas, Rect2(c + Vector2(0.18 * s, -0.75 * s), Vector2(0.42 * s, 1.5 * s)), 0.12 * s, G.NAVY, 0)
		"sound":
			var on: bool = G.data.sound
			var body := PackedVector2Array([c + Vector2(-0.85 * s, -0.3 * s), c + Vector2(-0.4 * s, -0.3 * s), c + Vector2(0.15 * s, -0.8 * s),
				c + Vector2(0.15 * s, 0.8 * s), c + Vector2(-0.4 * s, 0.3 * s), c + Vector2(-0.85 * s, 0.3 * s)])
			G.poly(canvas, body, G.NAVY, 0.0)
			if on:
				canvas.draw_arc(c + Vector2(0.2 * s, 0), 0.45 * s, -0.9, 0.9, 12, G.NAVY, 0.16 * s, true)
				canvas.draw_arc(c + Vector2(0.2 * s, 0), 0.8 * s, -0.9, 0.9, 12, G.NAVY, 0.16 * s, true)
			else:
				canvas.draw_line(c + Vector2(0.35 * s, -0.4 * s), c + Vector2(0.95 * s, 0.4 * s), G.RED, 0.2 * s, true)
				canvas.draw_line(c + Vector2(0.95 * s, -0.4 * s), c + Vector2(0.35 * s, 0.4 * s), G.RED, 0.2 * s, true)
		"music":
			var on2: bool = G.data.music
			canvas.draw_line(c + Vector2(-0.35 * s, 0.55 * s), c + Vector2(-0.35 * s, -0.75 * s), G.NAVY, 0.16 * s, true)
			canvas.draw_line(c + Vector2(0.55 * s, 0.35 * s), c + Vector2(0.55 * s, -0.95 * s), G.NAVY, 0.16 * s, true)
			canvas.draw_line(c + Vector2(-0.35 * s, -0.75 * s), c + Vector2(0.55 * s, -0.95 * s), G.NAVY, 0.3 * s, true)
			G.ellipse(canvas, c + Vector2(-0.55 * s, 0.6 * s), 0.3 * s, 0.22 * s, G.NAVY, 0.0, -0.4)
			G.ellipse(canvas, c + Vector2(0.35 * s, 0.4 * s), 0.3 * s, 0.22 * s, G.NAVY, 0.0, -0.4)
			if not on2:
				canvas.draw_line(c + Vector2(-0.9 * s, -0.9 * s), c + Vector2(0.9 * s, 0.9 * s), G.RED, 0.2 * s, true)
		"play":
			G.poly(canvas, PackedVector2Array([c + Vector2(-0.5 * s, -0.75 * s), c + Vector2(0.8 * s, 0), c + Vector2(-0.5 * s, 0.75 * s)]), G.NAVY, 0.0)
		"home":
			G.poly(canvas, PackedVector2Array([c + Vector2(0, -0.9 * s), c + Vector2(0.9 * s, -0.05 * s), c + Vector2(0.6 * s, -0.05 * s),
				c + Vector2(0.6 * s, 0.8 * s), c + Vector2(-0.6 * s, 0.8 * s), c + Vector2(-0.6 * s, -0.05 * s), c + Vector2(-0.9 * s, -0.05 * s)]), G.NAVY, 0.0)
		"retry":
			canvas.draw_arc(c, 0.65 * s, 0.6, TAU - 0.3, 24, G.NAVY, 0.25 * s, true)
			var tip := c + Vector2(cos(0.6), sin(0.6)) * 0.65 * s
