extends Node
## Headless self-test: plays every micro-game with its bot at each level and speed.

func _ready() -> void:
	var blast = load("res://scripts/blast.gd")
	var names: Array = blast.MICROS.keys()
	var report := []
	var fails := 0
	for n in names + ["BOSS"]:
		var line := "%-10s" % n
		for lvl in [1, 2, 3]:
			for sp in [1.0, 1.9]:
				var wins := 0
				var runs := 4
				for r in runs:
					var scr: GDScript = blast.BOSS if n == "BOSS" else blast.MICROS[n]
					var m = scr.new()
					add_child(m)
					m.init(1200, 900, lvl)
					var dt := 1.0 / 60.0
					var steps := 0
					while m.result == 0 and m.t < m.dur and steps < 2000:
						m.auto(dt * sp)
						m.step(dt * sp)
						steps += 1
					if m.result == 0 and m.survive:
						m.win()
					if m.result > 0:
						wins += 1
					m.free()
				line += " L%d@%.1f:%d/%d" % [lvl, sp, wins, runs]
				if wins < runs:
					fails += 1
		report.append(line)
	for l in report:
		print(l)
	print("SELFTEST_DONE fails=%d" % fails)
	get_tree().quit()

files.scripts/slime.gd:
extends "res://scripts/screen.gd"
## Squishy soft-body slime: grab, stretch, poke.

const COLORS := [
	["LIME", Color("8dff4f"), Color("3f9e1f")],
	["BUBBLEGUM", Color("ff8fc7"), Color("c2457f")],
	["OCEAN", Color("4fd8ff"), Color("1a7fb0")],
	["GALAXY", Color("7b4dff"), Color("2d1478")],
	["GOLD", Color("ffd84f"), Color("b98a0a")],
]
const N := 44
var b_back: Dictionary
var b_col: Dictionary
var pts: Array[Vector2] = []
var vel: Array[Vector2] = []
var rest: Array[Vector2] = []
var R := 220.0
var floor_y := 800.0
var area0 := 1.0
var grabs := {}   # touch index -> {pos, w:Array}
var col_i := 0
var squish_cd := 0.0
var glitter: Array = []


func setup() -> void:
	b_back = add_back(func(): G.main.go("fidget"))
	b_col = add_button("COLOR", G.LIME, next_color, 32)
	bg(Color("ffe08a"), Color("ffe9a8"), 2, 70, 0.15)
	G.play_music("chill")
	col_i = int(G.data.slime) % COLORS.size()
	b_col.col = COLORS[col_i][1]
	for k in 70:
		glitter.append({a = randf() * TAU, f = sqrt(randf()) * 0.85, s = randf_range(2, 5), tw = randf() * 10.0})


func next_color() -> void:
	col_i = (col_i + 1) % COLORS.size()
	G.data.slime = col_i
	b_col.col = COLORS[col_i][1]
	G.play("slurp")


func layout() -> void:
	place_back(b_back)
	b_col.rect = Rect2(W - 230 * U, 30 * U, 200 * U, 84 * U)
	R = minf(W, H) * 0.27
	floor_y = H - 70 * U
	var c := Vector2(W * 0.5, floor_y - R * 0.85)
	pts.clear(); vel.clear(); rest.clear()
	for i in N:
		var a := TAU * i / N
		var o := Vector2(cos(a), sin(a)) * R
		rest.append(o)
		pts.append(c + o)
		vel.append(Vector2.ZERO)
	area0 = poly_area()


func poly_area() -> float:
	var s := 0.0
	for i in N:
		var a := pts[i]
		var b := pts[(i + 1) % N]
		s += a.x * b.y - b.x * a.y
	return s * 0.5


func centroid() -> Vector2:
	var c := Vector2.ZERO
	for p in pts:
		c += p
	return c / N


func down(p: Vector2, i: int) -> void:
	var c := centroid()
	var near := false
	for q in pts:
		if q.distance_to(p) < R * 0.6:
			near = true
			break
	if not near and not Geometry2D.is_point_in_polygon(p, PackedVector2Array(pts)):
		return
	var w: Array = []
	var rad := R * 0.85
	for k in N:
		var d := pts[k].distance_to(p)
		w.append(clampf(1.0 - d / rad, 0.0, 1.0))
	var off: Array = []
	for k in N:
		off.append(pts[k] - p)
	grabs[i] = {pos = p, w = w, off = off}
	# poke: push nearby points away from the finger a little
	for k in N:
		vel[k] += (pts[k] - p).normalized() * 260.0 * U * w[k]
	play_squish()
	fx.burst(p, COLORS[col_i][1].lightened(0.3), 6, 160 * U, 7 * U)
	if c.distance_to(p) < R * 0.4:
		G.play("squish3", 0.9)


func drag(p: Vector2, i: int, rel: Vector2) -> void:
	if grabs.has(i):
		grabs[i].pos = p
		if rel.length() > 6.0 * U and squish_cd <= 0.0:
			play_squish()


func up(_p: Vector2, i: int) -> void:
	if grabs.has(i):
		grabs.erase(i)
		G.play("squish2", randf_range(0.9, 1.2), -4.0)


func play_squish() -> void:
	squish_cd = 0.16
	G.play("squish%d" % randi_range(1, 3), randf_range(0.85, 1.25), -3.0)


func update(dt: float) -> void:
	squish_cd -= dt
	var sub := 3
	var h := dt / sub
	for s in sub:
		var c := centroid()
		var cur_area := poly_area()
		var pressure := (area0 - cur_area) / area0
		# average rotation so the shape-matching target turns with the slime
		for k in N:
			var a := pts[k]
			var prev := pts[(k - 1 + N) % N]
			var nxt := pts[(k + 1) % N]
			var f := Vector2.ZERO
			# shape matching (gooey, so weak)
			f += (c + rest[k] * (0.92 if grabs.is_empty() else 1.0) - a) * (16.0 if grabs.is_empty() else 6.0)
			# neighbour springs
			var L := TAU * R / N
			for q in [prev, nxt]:
				var d: Vector2 = q - a
				var dl := d.length()
				if dl > 0.001:
					f += d / dl * (dl - L) * 60.0
			# pressure along outward normal
			var nrm := (nxt - prev).orthogonal().normalized()
			f += nrm * pressure * 2600.0 * U
			f.y += 700.0 * U
			vel[k] += f * h
		for g in grabs.values():
			for k in N:
				var wk: float = g.w[k]
				if wk > 0.0:
					var tgt: Vector2 = g.pos + g.off[k] * (1.0 - wk * 0.5)
					vel[k] = vel[k].lerp((tgt - pts[k]) / h * 0.12, wk * 0.35)
		for k in N:
			vel[k] *= 1.0 - 2.2 * h
			pts[k] += vel[k] * h
			if pts[k].y > floor_y:
				pts[k].y = floor_y
				vel[k].y = minf(0.0, vel[k].y) * -0.2
				vel[k].x *= 0.9
			pts[k].x = clampf(pts[k].x, 10 * U, W - 10 * U)
			pts[k].y = maxf(pts[k].y, 120 * U)
	# keep it from tearing: limit distance from centroid
	var cc := centroid()
	for k in N:
		var d := pts[k] - cc
		if d.length() > R * 2.6:
			pts[k] = cc + d.normalized() * R * 2.6


func smooth() -> PackedVector2Array:
	var out := PackedVector2Array()
	for k in N:
		var p0 := pts[(k - 1 + N) % N]
		var p1 := pts[k]
		var p2 := pts[(k + 1) % N]
		var p3 := pts[(k + 2) % N]
		for s in 3:
			var t := s / 3.0
			var t2 := t * t
			var t3 := t2 * t
			out.append(0.5 * ((2.0 * p1) + (-p0 + p2) * t + (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3) * t2 + (-p0 + 3.0 * p1 - 3.0 * p2 + p3) * t3))
	return out


func paint() -> void:
	title_text(Vector2(W * 0.5, 70 * U), "SLIME", 70, false)
	G.txt(self, Vector2(W * 0.5, 140 * U), "Grab it, stretch it, poke it!", int(28 * U), G.NAVY, 0, G.font_bold)
	G.rrect(self, Rect2(-20 * U, floor_y, W + 40 * U, H), 0, Color("c98a4b"), 6 * U)
	var poly := smooth()
	if Geometry2D.triangulate_polygon(poly).is_empty():
		poly = Geometry2D.convex_hull(poly)
	var cs: Array = COLORS[col_i]
	var c := centroid()
	# shadow
	G.ellipse(self, Vector2(c.x, floor_y + 6 * U), R * 1.1, R * 0.12, Color(0, 0, 0, 0.2), 0)
	var outline := Geometry2D.offset_polygon(poly, 7 * U, Geometry2D.JOIN_ROUND)
	if outline.size() > 0:
		draw_colored_polygon(outline[0], cs[2])
	draw_colored_polygon(poly, cs[1])
	var inner := PackedVector2Array()
	for p in poly:
		inner.append(c + (p - c) * 0.78 + Vector2(-R * 0.04, -R * 0.06))
	if not Geometry2D.triangulate_polygon(inner).is_empty():
		draw_colored_polygon(inner, cs[1].lightened(0.18))
	# glitter that follows the squish
	for g in glitter:
		var k := int(round(g.a / TAU * N)) % N
		var edge := pts[k]
		var gp: Vector2 = c + (edge - c) * g.f
		var tw: float = 0.5 + 0.5 * sin(T * 4.0 + g.tw)
		draw_circle(gp, g.s * U * (0.6 + tw * 0.6), Color(1, 1, 1, 0.35 + 0.5 * tw) if col_i != 3 else Color(1, 0.95, 0.6, 0.5 + 0.5 * tw), true, -1.0, true)
	# highlights
	var top := pts[N * 3 / 4]
	var hl := c.lerp(top, 0.6) + Vector2(-R * 0.25, 0)
	G.ellipse(self, hl, R * 0.32, R * 0.12, Color(1, 1, 1, 0.55), 0, -0.3)
	draw_circle(hl + Vector2(R * 0.32, R * 0.04), R * 0.05, Color(1, 1, 1, 0.7), true, -1.0, true)
	# cute face on the slime
	var ey := c + Vector2(0, -R * 0.1)
	var squished := grabs.size() > 0
	if squished:
		for sx in [-1.0, 1.0]:
			var e: Vector2 = ey + Vector2(sx * R * 0.22, 0)
			draw_line(e + Vector2(-R * 0.07, -R * 0.05 * sx * 0.0 - R * 0.04), e + Vector2(R * 0.07, 0), G.NAVY, 6 * U, true)
			draw_line(e + Vector2(-R * 0.07, R * 0.04), e + Vector2(R * 0.07, 0), G.NAVY, 6 * U, true)
		G.ellipse(self, ey + Vector2(0, R * 0.22), R * 0.1, R * 0.08, Color("5b1a3a"), 4 * U)
	else:
		G.eyes(self, ey, R * 0.09, Vector2(0, 0.3), 0.0, 2.0)
		G.smile(self, ey + Vector2(0, R * 0.16), R * 0.25, 1.0, 6 * U)

files.scripts/spinner.gd:
extends "res://scripts/screen.gd"
## Fidget spinner: flick to spin.

const SKINS := [
	["CHROME", Color("c9d2e3"), Color("7f8aa3")],
	["FIRE", Color("ff6b35"), Color("c0392b")],
	["OCEAN", Color("2ec4ff"), Color("1769aa")],
	["GOLD", Color("ffd23f"), Color("c99a06")],
	["GALAXY", Color("8b5cf6"), Color("3a0ca3")],
	["LIME", Color("7cf05a"), Color("2f9e44")],
]
var b_back: Dictionary
var b_skin: Dictionary
var skin := 0
var ang := 0.0
var w := 0.0
var c := Vector2.ZERO
var R := 250.0
var grab := -1
var last_a := 0.0
var last_t := 0.0
var hist: Array = []
var best_now := 0.0


func setup() -> void:
	b_back = add_back(func(): G.main.go("fidget"))
	b_skin = add_button("COLOR", G.PURPLE, func():
		skin = (skin + 1) % SKINS.size()
		G.play("click", 1.4), 32)
	bg(Color("2a1b3d"), Color("33244a"), 3, 90, 0.2)
	G.play_music("chill")
	if G.data.sound:
		G.whir.play()


func layout() -> void:
	place_back(b_back)
	b_skin.rect = Rect2(W - 230 * U, 30 * U, 200 * U, 84 * U)
	c = Vector2(W * 0.5, H * 0.55)
	R = minf(W, H) * 0.3


func down(p: Vector2, i: int) -> void:
	if p.distance_to(c) < R * 1.6:
		grab = i
		last_a = (p - c).angle()
		last_t = T
		hist.clear()


func drag(p: Vector2, i: int, _rel: Vector2) -> void:
	if grab != i:
		return
	var a := (p - c).angle()
	var da := wrapf(a - last_a, -PI, PI)
	var dt := maxf(T - last_t, 0.008)
	ang += da
	hist.append([T, da / dt])
	while hist.size() > 6:
		hist.pop_front()
	last_a = a
	last_t = T
	w = lerpf(w, da / dt, 0.5)


func up(_p: Vector2, i: int) -> void:
	if grab == i:
		grab = -1
		if hist.size() > 0:
			var s := 0.0
			for h in hist:
				s += h[1]
			w = clampf(s / hist.size() * 1.4, -95.0, 95.0)
			if absf(w) > 6.0:
				G.play("swish", 0.8 + absf(w) / 80.0)


func update(dt: float) -> void:
	if grab < 0:
		ang += w * dt
		w = move_toward(w, 0.0, (0.35 + absf(w) * 0.06) * dt)
	var rpm := absf(w) * 60.0 / TAU
	best_now = maxf(best_now, rpm)
	if rpm > G.data.spin_best:
		G.data.spin_best = int(rpm)
	if G.data.sound:
		if not G.whir.playing:
			G.whir.play()
		G.whir.volume_db = linear_to_db(clampf(rpm / 300.0, 0.0, 1.0) * 0.8 + 0.0001)
		G.whir.pitch_scale = clampf(0.5 + rpm / 400.0, 0.5, 2.5)
	else:
		G.whir.stop()


func _exit_tree() -> void:
	G.whir.stop()
	G.save_game()


func draw_body(a: float, alpha: float) -> void:
	var sk: Array = SKINS[skin]
	var arm := R * 0.62
	var lobes: Array = []
	for k in 3:
		lobes.append(c + Vector2(cos(a + k * TAU / 3.0), sin(a + k * TAU / 3.0)) * arm)
	# body: triangle joining the lobes, edges drawn as thick rounded bars
	var tri := PackedVector2Array([lobes[0], lobes[1], lobes[2]])
	for k in 3:
		G.seg(self, lobes[k], lobes[(k + 1) % 3], Color(sk[2], alpha), R * 0.34, Color(G.NAVY, alpha), 7 * U)
	draw_colored_polygon(tri, Color(sk[2], alpha))
	for k in 3:
		G.seg(self, c, lobes[k], Color(sk[2], alpha), R * 0.4, Color(G.NAVY, alpha), 0)
	for k in 3:
		var d := Vector2(cos(a + k * TAU / 3.0), sin(a + k * TAU / 3.0))
		var p := c + d * arm
		G.circ(self, p, R * 0.36, Color(sk[1], alpha), 7 * U, Color(G.NAVY, alpha))
		G.circ(self, p, R * 0.22, Color(0.85, 0.87, 0.92, alpha), 5 * U, Color(G.NAVY, alpha))
		for b in 6:
			var ba := -a * 0.6 + b * TAU / 6.0
			draw_circle(p + Vector2(cos(ba), sin(ba)) * R * 0.15, R * 0.035, Color(0.5, 0.55, 0.65, alpha), true, -1.0, true)
	G.circ(self, c, R * 0.3, Color(sk[1], alpha), 7 * U, Color(G.NAVY, alpha))
	G.circ(self, c, R * 0.2, Color(0.9, 0.92, 0.96, alpha), 5 * U, Color(G.NAVY, alpha))


func paint() -> void:
	title_text(Vector2(W * 0.5, 70 * U), "SPINNER", 70, false)
	var rpm := absf(w) * 60.0 / TAU
	draw_circle(c + Vector2(0, R * 1.05), R * 0.9, Color(0, 0, 0, 0.15), true, -1.0, true)
	if rpm > 200.0:
		var blur := clampf((rpm - 200.0) / 400.0, 0.0, 1.0)
		draw_circle(c, R * 0.98, Color(SKINS[skin][1], 0.25 * blur), true, -1.0, true)
		for k in 4:
			draw_body(ang - w * 0.004 * (k + 1), 0.18)
	draw_body(ang, 1.0)
	G.shine(self, c, R * 0.3, 0.6)
	G.txt(self, Vector2(W * 0.5, H - 110 * U), "%d RPM" % int(rpm), int(64 * U), G.YELLOW if rpm < 400 else G.PINK, int(12 * U))
	G.txt(self, Vector2(W * 0.5, H - 50 * U), "Record: %d RPM   -   Flick it fast!" % int(G.data.spin_best), int(28 * U), Color.WHITE, int(6 * U), G.font_bold)

