extends "res://scripts/micro.gd"

var bugs: Array = []


func setup() -> void:
	word = "BOOP!"
	hint = "Boop the bug!"
	dur = 4.5
	c1 = Color("7cf05a"); c2 = Color("9cf57f"); pat = 2
	for i in (1 if lvl == 1 else 2):
		bugs.append({p = rnd_in(120), tgt = rnd_in(120), sp = (260 + lvl * 90) * U, state = 0, dz = 0.0, v = Vector2.ZERO})


func tick(dt: float) -> void:
	for b in bugs:
		if b.state == 0:
			var d: Vector2 = b.tgt - b.p
			if d.length() < 30 * U:
				b.tgt = rnd_in(110)
			b.p += d.normalized() * b.sp * dt
		else:
			b.dz += dt
			b.v.y -= 900 * U * dt
			b.p += b.v * dt


func down(p: Vector2, _i: int) -> void:
	if result != 0:
		return
	for b in bugs:
		if b.state == 0 and p.distance_to(b.p) < 80 * U:
			b.state = 1
			b.v = Vector2(randf_range(-200, 200), -200) * U
			G.play("boop", randf_range(0.9, 1.2))
			fx.stars(b.p, 6, 260 * U)
			fx.text(b.p - Vector2(0, 40 * U), "BOOP!", G.YELLOW, 46 * U)
			break
	for b in bugs:
		if b.state == 0:
			return
	win()


func auto(_dt: float) -> void:
	if int(t * 60) % 25 == 0:
		for b in bugs:
			if b.state == 0:
				down(b.p, 0)
				return


func paint() -> void:
	for b in bugs:
		var p: Vector2 = b.p
		var r := 48.0 * U
		var face := 1.0 if (b.tgt.x - p.x) >= 0.0 else -1.0
		# wings
		var fl := absf(sin(t * 40.0)) * 0.6 + 0.4
		for sx in [-1.0, 1.0]:
			G.ellipse(self, p + Vector2(sx * r * 0.55, -r * 0.7), r * 0.45, r * 0.75 * fl, Color(0.85, 0.95, 1.0, 0.75), 3 * U, sx * 0.5)
		G.circ(self, p, r, Color("e8384f"), 5 * U)
		draw_line(p + Vector2(0, -r), p + Vector2(0, r), G.NAVY, 4 * U, true)
		for q in [Vector2(-0.45, -0.2), Vector2(0.45, 0.25), Vector2(-0.35, 0.5), Vector2(0.4, -0.45)]:
			draw_circle(p + q * r, r * 0.16, G.NAVY, true, -1.0, true)
		var hp := p + Vector2(face * r * 0.95, -r * 0.1)
		G.circ(self, hp, r * 0.5, G.NAVY, 0)
		if b.state == 0:
			G.eyes(self, hp + Vector2(face * r * 0.1, -r * 0.05), r * 0.18, Vector2(face, 0))
		else:
			G.txt(self, hp, "@ @", int(r * 0.4), Color.WHITE, 0, G.font_bold)
		G.shine(self, p, r)

