			opts.append(o)
	opts.shuffle()


func btn_rect(k: int) -> Rect2:
	var w := 170.0 * U
	var gap := 40.0 * U
	var x0 := W * 0.5 - (3 * w + 2 * gap) * 0.5
	return Rect2(x0 + k * (w + gap), area.end.y - 140 * U, w, 130 * U)


func tick(dt: float) -> void:
	for d in ducks:
		d.p.x += d.v * dt * (0.6 + lvl * 0.3)
		if d.p.x < area.position.x + 50 * U or d.p.x > area.end.x - 50 * U:
			d.v = -d.v
			d.p.x = clampf(d.p.x, area.position.x + 50 * U, area.end.x - 50 * U)


func down(p: Vector2, _i: int) -> void:
	if result != 0:
		return
	for k in 3:
		if btn_rect(k).has_point(p):
			picked = k
			if opts[k] == n:
				G.play("ding")
				win("YES! %d!" % n)
			else:
				lose("It was %d!" % n)
			return


func auto(_dt: float) -> void:
	if t > 1.0:
		down(btn_rect(opts.find(n)).get_center(), 0)


func paint() -> void:
	draw_rect(Rect2(0, area.position.y + 20 * U, W, area.size.y - 190 * U), Color(0.1, 0.45, 0.9, 0.25))
	for d in ducks:
		var p: Vector2 = d.p + Vector2(0, sin(t * 3.0 + d.ph) * 6 * U)
		var f := 1.0 if d.v > 0 else -1.0
		var r := 42.0 * U
		G.ellipse(self, p, r * 1.25, r * 0.8, G.YELLOW, 5 * U)
		G.circ(self, p + Vector2(f * r * 0.85, -r * 0.8), r * 0.55, G.YELLOW, 5 * U)
		G.poly(self, PackedVector2Array([p + Vector2(f * r * 1.3, -r * 0.85), p + Vector2(f * r * 1.85, -r * 0.7), p + Vector2(f * r * 1.3, -r * 0.55)]), G.ORANGE, 3 * U)
		draw_circle(p + Vector2(f * r * 1.0, -r * 0.95), r * 0.11, G.NAVY, true, -1.0, true)
		G.ellipse(self, p + Vector2(-f * r * 0.2, -r * 0.05), r * 0.55, r * 0.3, Color("ffbf1f"), 3 * U, -0.3 * f)
	for k in 3:
		var r := btn_rect(k)
		var col: Color = G.PURPLE
		if picked == k:
			col = G.LIME if opts[k] == n else G.RED
		G.rrect(self, Rect2(r.position + Vector2(0, 10 * U), r.size), 26 * U, col.darkened(0.35), 6 * U)
		G.rrect(self, r, 26 * U, col, 6 * U)
		G.txt(self, r.get_center(), str(opts[k]), int(72 * U))

