extends "res://scripts/micro.gd"

var px := 0.0
var tx := 0.0
var py := 0.0
var drops: Array = []
var spawn := 0.0
var hit := false


func setup() -> void:
	word = "DODGE!"
	hint = "Don't get hit by the boring rain!"
	dur = 5.0
	survive = true
	c1 = Color("8b5cf6"); c2 = Color("a07cf8"); pat = 1
	px = W * 0.5
	tx = px
	py = area.end.y - 60 * U


func tick(dt: float) -> void:
	px = move_toward(px, tx, 1500 * U * dt)
	if result == 0 and t < dur - 0.6:
		spawn -= dt
		if spawn <= 0.0:
			spawn = 0.55 - lvl * 0.07
			var x := randf_range(area.position.x + 40 * U, area.end.x - 40 * U)
			if randf() < 0.3:
				x = clampf(px + randf_range(-60, 60) * U, area.position.x + 40 * U, area.end.x - 40 * U)
			drops.append({p = Vector2(x, area.position.y - 30 * U), v = (380 + lvl * 70) * U})
	for d in drops:
		d.p.y += d.v * dt
		if result == 0 and d.p.distance_to(Vector2(px, py)) < 60 * U:
			hit = true
			G.play("splat")
			fx.burst(d.p, G.BLOB, 16, 320 * U)
			lose("SPLASH!")


func down(p: Vector2, _i: int) -> void:
	tx = clampf(p.x, area.position.x + 60 * U, area.end.x - 60 * U)


func drag(p: Vector2, i: int, _r: Vector2) -> void:
	down(p, i)


func auto(_dt: float) -> void:
	var best := px
	var bs := -99999.0
	for k in 25:
		var x := lerpf(area.position.x + 60 * U, area.end.x - 60 * U, k / 24.0)
		var s := 99999.0
		for d in drops:
			var dy: float = py - d.p.y
			if dy > -30 * U and dy < 420 * U:
				var arrive: float = dy / d.v
				var reach := absf(x - px) / (1500 * U)
				var gap: float = absf(d.p.x - x)
				# a drop between here and x that lands before we pass it also blocks the path
				var lo := minf(px, x) - 70 * U
				var hi := maxf(px, x) + 70 * U
				if d.p.x > lo and d.p.x < hi and arrive < reach + 0.1:
					gap = minf(gap, 0.0)
				s = minf(s, gap)
		s -= absf(x - px) * 0.05
		if s > bs:
			bs = s
			best = x
	tx = best


func paint() -> void:
	for d in drops:
		var p: Vector2 = d.p
		var pts := PackedVector2Array()
		for k in 24:
			var a := TAU * k / 24.0
			var r := 26.0 * U
			var q := Vector2(cos(a) * r, sin(a) * r)
			if q.y < 0:
				q.y *= 1.0 + 0.9 * (1.0 - absf(cos(a)))
			pts.append(p + q)
		G.poly(self, pts, G.BLOB, 4 * U)
		draw_line(p + Vector2(-9, 2) * U, p + Vector2(-3, 2) * U, G.NAVY, 3 * U)
		draw_line(p + Vector2(3, 2) * U, p + Vector2(9, 2) * U, G.NAVY, 3 * U)
	G.buddy(self, Vector2(px, py), 58 * U, G.YELLOW, t, 2 if hit else 1, Vector2((tx - px) / 200.0, -1))

