var food: Array = []
var mouth := Vector2.ZERO
var held := -1
var chew := 0.0
var eaten := 0


func setup() -> void:
	word = "FEED!"
	hint = "Drag the donut into the mouth!"
	dur = 5.0
	c1 = Color("ff8a3d"); c2 = Color("ffa66b"); pat = 2
	mouth = Vector2(area.end.x - 200 * U, area.get_center().y)
	for i in (2 if lvl == 3 else 1):
		food.append({p = Vector2(area.position.x + 150 * U, area.get_center().y + (i - 0.5) * 220 * U * float(lvl == 3)), alive = true, col = [G.PINK, G.CYAN][i]})


func tick(dt: float) -> void:
	if lvl >= 2:
		mouth.y = area.get_center().y + sin(t * 2.4) * area.size.y * 0.3
	chew = maxf(0.0, chew - dt)
	for f in food:
		if f.alive and f.p.distance_to(mouth) < 95 * U:
			f.alive = false
			held = -1
			eaten += 1
			chew = 0.6
			G.play("nom")
			fx.burst(mouth, f.col, 14, 300 * U)
			fx.text(mouth - Vector2(0, 150 * U), "NOM!", G.YELLOW, 56 * U)
			if eaten == food.size():
				win()


func down(p: Vector2, _i: int) -> void:
	for k in food.size():
		if food[k].alive and p.distance_to(food[k].p) < 95 * U:
			held = k
			return


func drag(p: Vector2, _i: int, _r: Vector2) -> void:
	if held >= 0 and food[held].alive:
		food[held].p = p


func up(_p: Vector2, _i: int) -> void:
	held = -1


func auto(dt: float) -> void:
	for k in food.size():
		if food[k].alive:
			if held != k:
				down(food[k].p, 0)
			var p: Vector2 = food[k].p
			drag(p.move_toward(mouth, 1400 * U * dt), 0, Vector2.ZERO)
			return


func paint() -> void:
	var c := mouth + Vector2(70 * U, 0)
	var r := 150.0 * U
	var fur := PackedVector2Array()
	for k in 48:
		var a := TAU * k / 48.0
		fur.append(c + Vector2(cos(a), sin(a)) * r * (1.0 + 0.07 * (k % 2)))
	G.poly(self, fur, G.PURPLE, 6 * U)
	G.eyes(self, c + Vector2(10 * U, -r * 0.5), r * 0.2, (food[0].p - c).normalized() if food.size() > 0 else Vector2.ZERO)
	var open := 0.35 if chew > 0.0 and fmod(chew, 0.2) < 0.1 else 1.0
	G.ellipse(self, mouth, 80 * U, 70 * U * open, Color("5b1a3a"), 6 * U)
	if open > 0.5:
		G.ellipse(self, mouth + Vector2(0, 35 * U), 45 * U, 22 * U, Color("ff6b8f"), 0)
		for k in 3:
			G.poly(self, PackedVector2Array([mouth + Vector2(-40 + k * 30, -65) * U, mouth + Vector2(-25 + k * 30, -65) * U, mouth + Vector2(-32 + k * 30, -45) * U]), Color.WHITE, 2 * U)
	for f in food:
		if f.alive:
			var p: Vector2 = f.p
			G.circ(self, p, 62 * U, Color("e3a25a"), 5 * U)
			G.circ(self, p, 52 * U, f.col, 0)
			G.circ(self, p, 20 * U, c1, 5 * U)
			for k in 8:
				var a := k * 0.8
				draw_line(p + Vector2(cos(a), sin(a)) * 32 * U, p + Vector2(cos(a), sin(a)) * 42 * U, G.RAINBOW[k % 6], 5 * U, true)

