extends "res://scripts/micro.gd"

var fuel := 0.0
var holding := false
var z0 := 0.6
var zw := 0.2
var state := 0  # 0 fuelling, 1 flying, 2 fizzle
var ry := 0.0
var rv := 0.0


func setup() -> void:
	word = "LAUNCH!"
	hint = "HOLD to fuel, let go in the GREEN!"
	dur = 5.0
	c1 = Color("2a1b5d"); c2 = Color("3b2a7d"); pat = 1
	zw = 0.26 - lvl * 0.05
	z0 = randf_range(0.45, 0.92 - zw)


func tick(dt: float) -> void:
	if state == 0 and holding:
		fuel += (0.42 + lvl * 0.1) * dt
		if fuel >= 1.0:
			fuel = 1.0
			holding = false
			release()
	if state == 1:
		rv -= 1900 * U * dt
		ry += rv * dt
		fx.puff(rocket_pos() + Vector2(0, 110 * U), Color(1, 0.7, 0.3, 0.9), 2, 120 * U)
	elif state == 2:
		rv += 1600 * U * dt
		ry = minf(0.0, ry + rv * dt)


func rocket_pos() -> Vector2:
	return Vector2(W * 0.5 - 60 * U, area.end.y - 150 * U + ry)


func release() -> void:
	if state != 0 or result != 0:
		return
	if fuel >= z0 and fuel <= z0 + zw:
		state = 1
		G.play("rocket")
		win("LIFT OFF!")
	else:
		state = 2
		rv = -700 * U if fuel < z0 else -300 * U
		G.play("puff", 0.6)
		fx.puff(rocket_pos() + Vector2(0, 100 * U), Color(0.7, 0.7, 0.7, 0.9), 14, 200 * U)
		lose("TOO LITTLE!" if fuel < z0 else "TOO MUCH!")


func down(_p: Vector2, _i: int) -> void:
	if state == 0:
		holding = true
		G.play("pump", 0.8, -6.0)


func up(_p: Vector2, _i: int) -> void:
	if holding:
		holding = false
		release()


func auto(_dt: float) -> void:
	if state == 0 and not holding and t > 0.3:
		down(Vector2.ZERO, 0)
	if holding and fuel >= z0 + zw * 0.5:
		up(Vector2.ZERO, 0)


func paint() -> void:
	ground(area.end.y - 40 * U, Color("8a8fa8"), Color("6a6f88"))
	var c := rocket_pos()
	if state == 1:
		var fl := PackedVector2Array([c + Vector2(-30 * U, 100 * U), c + Vector2(0, (190 + sin(t * 40) * 20) * U), c + Vector2(30 * U, 100 * U)])
		G.poly(self, fl, G.ORANGE, 4 * U)
	G.poly(self, PackedVector2Array([c + Vector2(-45 * U, 60 * U), c + Vector2(-90 * U, 110 * U), c + Vector2(-45 * U, 100 * U)]), G.RED, 5 * U)
	G.poly(self, PackedVector2Array([c + Vector2(45 * U, 60 * U), c + Vector2(90 * U, 110 * U), c + Vector2(45 * U, 100 * U)]), G.RED, 5 * U)
	var body := PackedVector2Array()
	for k in 21:
		var a := k / 20.0
		body.append(c + Vector2(-50 * U * sin(a * PI * 0.5 + 0.2), -130 * U + a * 230 * U))
	for k in 21:
		var a := 1.0 - k / 20.0
		body.append(c + Vector2(50 * U * sin(a * PI * 0.5 + 0.2), -130 * U + a * 230 * U))
	G.poly(self, body, Color("f2f4fb"), 5 * U)
	G.circ(self, c + Vector2(0, -30 * U), 24 * U, G.CYAN, 5 * U)
	G.shine(self, c + Vector2(0, -30 * U), 24 * U)
	# gauge
	var gr := Rect2(W * 0.5 + 160 * U, area.position.y + 20 * U, 70 * U, area.size.y - 80 * U)
	G.rrect(self, gr, 20 * U, Color("1c1430"), 6 * U)
	var inner := gr.grow(-10 * U)
	var zr := Rect2(inner.position.x, inner.end.y - inner.size.y * (z0 + zw), inner.size.x, inner.size.y * zw)
	draw_rect(zr, Color(0.49, 0.94, 0.35, 0.6))
	var fh := inner.size.y * fuel
	draw_rect(Rect2(inner.position.x + 8 * U, inner.end.y - fh, inner.size.x - 16 * U, fh), G.ORANGE)
	draw_rect(zr, G.LIME, false, 4 * U)
	G.txt(self, Vector2(gr.get_center().x, gr.position.y - 10 * U), "FUEL", int(30 * U))

