	c1 = Color("2ec4ff"); c2 = Color("63d6ff"); pat = 1
	var n := 2 + lvl
	for i in n:
		var x := lerpf(area.position.x + 110 * U, area.end.x - 110 * U, (i + 0.5) / n) + randf_range(-30, 30) * U
		var y := randf_range(area.position.y + 260 * U, area.end.y - 40 * U)
		balloons.append({p = Vector2(x, y), r = randf_range(62, 72) * U, col = G.RAINBOW[(i * 2 + randi()) % 6],
			ph = randf() * TAU, sp = (randf_range(35, 60) + lvl * 22) * U, alive = true})


func tick(dt: float) -> void:
	for b in balloons:
		if b.alive:
			b.p.y -= b.sp * dt
			b.p.x += sin(t * 2.2 + b.ph) * 40.0 * U * dt * lvl
			if b.p.y < area.position.y + b.r * 1.2:
				b.p.y = area.position.y + b.r * 1.2
				b.sp = -absf(b.sp) * 0.5
			if b.p.y > area.end.y:
				b.sp = absf(b.sp)


func down(p: Vector2, _i: int) -> void:
	if result != 0:
		return
	for b in balloons:
		if b.alive and p.distance_to(b.p) < b.r * 1.2:
			b.alive = false
			G.play("pop%d" % randi_range(1, 3), randf_range(0.9, 1.15))
			fx.burst(b.p, b.col, 22, 520 * U, 11 * U)
			fx.ring(b.p, Color.WHITE, b.r)
			fx.text(b.p, "POP!", G.YELLOW, 48 * U)
			break
	for b in balloons:
		if b.alive:
			return
	win()


func auto(_dt: float) -> void:
	if int(t * 60) % 20 == 0:
		for b in balloons:
			if b.alive:
				down(b.p, 0)
				return


func paint() -> void:
