			continue
		var p: Vector2 = b.p
		var r: float = b.r
		var s := PackedVector2Array()
		for k in 12:
			s.append(p + Vector2(sin(k * 0.9 + t * 4.0) * 8.0 * U, r * 1.15 + k * 12.0 * U))
		draw_polyline(s, G.NAVY, 3 * U, true)
		G.poly(self, PackedVector2Array([p + Vector2(0, r * 1.05), p + Vector2(-12 * U, r * 1.25), p + Vector2(12 * U, r * 1.25)]), b.col.darkened(0.2), 4 * U)
		var pts := PackedVector2Array()
		for k in 40:
			var a := TAU * k / 40.0
			var rr := r * (1.0 + 0.08 * maxf(0.0, sin(a)))
			pts.append(p + Vector2(cos(a) * r * 0.92, sin(a) * rr * 1.12))
		G.poly(self, pts, b.col, 5 * U)
		G.shine(self, p, r, 0.6)

files.scripts/micro/pump.gd:
extends "res://scripts/micro.gd"

var taps := 0.0
var need := 10
var press := 0.0
var popped := false
var col := Color.WHITE


func setup() -> void:
	word = "PUMP!"
	hint = "Tap super fast to blow it up!"
	dur = 5.0
	c1 = Color("ff3d7f"); c2 = Color("ff6b9a"); pat = 0
	need = 8 + lvl * 3
	col = G.RAINBOW[randi() % 6]


func tick(dt: float) -> void:
	press = maxf(0.0, press - dt * 6.0)
	if lvl == 3 and not popped:
		taps = maxf(0.0, taps - dt * 0.8)


func down(_p: Vector2, _i: int) -> void:
	if popped or result != 0:
		return
	taps += 1.0
	press = 1.0
	G.play("puff", 0.8 + taps / need * 0.8)
	if taps >= need:
		popped = true
		G.play("pop1", 0.7)
		var c := balloon_center()
		fx.burst(c, col, 40, 900 * U, 14 * U)
		fx.confetti(c, 40, 900 * U)
		win("BANG!")


func auto(_dt: float) -> void:
	if int(t * 60) % 6 == 0:
		down(Vector2.ZERO, 0)


func balloon_center() -> Vector2:
	var f := clampf(taps / need, 0.0, 1.0)
	var r := lerpf(40.0, 230.0, f) * U
	return Vector2(W * 0.5 + 110 * U, area.end.y - 240 * U - r)


func paint() -> void:
	var base := Vector2(W * 0.5 - 140 * U, area.end.y)
	ground(area.end.y + 4 * U, Color("bfe9ff"), Color("9ad7f7"))
	# pump
	var hy := -260.0 * U + press * 90.0 * U
	G.rrect(self, Rect2(base + Vector2(-50, -230) * U, Vector2(100, 230) * U), 18 * U, G.RED, 6 * U)
	G.seg(self, base + Vector2(0, -230 * U), base + Vector2(0, hy), Color("cfd6e6"), 14 * U, G.NAVY, 4 * U)
	G.seg(self, base + Vector2(-80 * U, hy), base + Vector2(80 * U, hy), G.NAVY, 24 * U, G.NAVY, 0)
	# hose
	var c := balloon_center()
	var f := clampf(taps / need, 0.0, 1.0)
	var r := lerpf(40.0, 230.0, f) * U
	var hose := PackedVector2Array()
	var a := base + Vector2(50 * U, -40 * U)
	var b := Vector2(c.x, c.y + r + 30 * U)
	for k in 17:
		var u := k / 16.0
		hose.append(a.lerp(b, u) + Vector2(0, sin(u * PI) * 70 * U))
	draw_polyline(hose, G.NAVY, 18 * U, true)
	draw_polyline(hose, Color("4a4a5a"), 10 * U, true)
	if not popped:
		var wob := sin(t * 30.0) * 0.03 * f
		G.ellipse(self, c, r * (0.95 + wob), r * (1.08 - wob), col, 6 * U)
		G.poly(self, PackedVector2Array([c + Vector2(0, r * 1.05), c + Vector2(-16 * U, r * 1.05 + 28 * U), c + Vector2(16 * U, r * 1.05 + 28 * U)]), col.darkened(0.2), 4 * U)
		G.shine(self, c, r, 0.55)
		if f > 0.3:
			G.eyes(self, c + Vector2(0, -r * 0.1), r * 0.15, Vector2(0, 0.3), 0.0)
			G.ellipse(self, c + Vector2(0, r * 0.35), r * 0.12 * f, r * 0.15 * f, Color("5b1a3a"), 4 * U)
		G.txt(self, Vector2(W * 0.5, area.position.y + 30 * U), "%d / %d" % [int(taps), need], int(52 * U))

files.scripts/micro/slice.gd:
extends "res://scripts/micro.gd"

var fruits: Array = []
var halves: Array = []
var trail: Array = []
var last := Vector2.ZERO
var has_last := false
const KINDS := [[Color("3fbf4f"), Color("ff4d6a"), 70.0], [Color("ff9a1f"), Color("ffc65c"), 52.0], [Color("e8384f"), Color("fff1c9"), 50.0]]


func setup() -> void:
	word = "SLICE!"
	hint = "Swipe through all the fruit!"
	dur = 4.6
	c1 = Color("ff8a3d"); c2 = Color("ffa463"); pat = 0
	var n := 1 + lvl
	for i in n:
		var x := lerpf(area.position.x + 180 * U, area.end.x - 180 * U, (i + 0.5) / n)
		var k: Array = KINDS[randi() % 3]
		fruits.append({p = Vector2(x, H + 60 * U), v = Vector2(randf_range(-80, 80) * U, -randf_range(1050, 1180) * U),
			start = i * 0.35, live = 0, k = k, rot = 0.0})


func tick(dt: float) -> void:
	var g := 1100.0 * U
	for f in fruits:
		if f.live == 0 and t >= f.start:
			f.live = 1
			G.play("whoosh", 1.3, -8.0)
		if f.live == 1:
			f.v.y += g * dt
			f.p += f.v * dt
			f.rot += dt * 3.0
			if f.v.y > 0 and f.p.y > H + 80 * U:
				f.live = 3
				lose("MISSED ONE!")
	for h in halves:
		h.v.y += g * dt
		h.p += h.v * dt
		h.rot += h.vr * dt
	for tr in trail:
		tr.life -= dt
	while trail.size() > 0 and trail[0].life <= 0.0:
		trail.pop_front()


func cut(a: Vector2, b: Vector2) -> void:
	for f in fruits:
		if f.live == 1:
			var q := Geometry2D.get_closest_point_to_segment(f.p, a, b)
			if q.distance_to(f.p) < f.k[2] * U:
				f.live = 2
				G.play("swish", 1.4)
				G.play("splat", 1.5, -4.0)
				var d := (b - a).normalized()
				var n := d.orthogonal()
				for s in [-1.0, 1.0]:
					halves.append({p = f.p + n * s * 10 * U, v = f.v * 0.3 + n * s * 280 * U, rot = d.angle() + (0.0 if s > 0 else PI), vr = s * 4.0, k = f.k})
				fx.burst(f.p, f.k[1], 20, 420 * U)
	for f in fruits:
		if f.live != 2:
			return
	win("JUICY!")


func down(p: Vector2, _i: int) -> void:
	last = p
	has_last = true


func drag(p: Vector2, _i: int, _r: Vector2) -> void:
	if has_last:
		trail.append({a = last, b = p, life = 0.18})
		if last.distance_to(p) > 2.0:
			cut(last, p)
	last = p
	has_last = true


func up(_p: Vector2, _i: int) -> void:
	has_last = false


func auto(_dt: float) -> void:
	for f in fruits:
		if f.live == 1 and f.v.y > -500 * U:
			down(f.p + Vector2(-120, -40) * U, 0)
			drag(f.p + Vector2(120, 40) * U, 0, Vector2.ZERO)
			up(f.p, 0)
			return


func draw_fruit(p: Vector2, k: Array, rot: float, half := false) -> void:
	var r: float = k[2] * U
	if not half:
		G.circ(self, p, r, k[0], 5 * U)
		if k[0] == KINDS[0][0]:
			for s in 4:
				var a := rot + s * 0.8
				draw_arc(p, r * 0.75, a, a + 0.5, 8, Color("1f7a2c"), 6 * U, true)
		G.shine(self, p, r)
	else:
		var pts := PackedVector2Array()
		for s in 19:
			var a := rot + PI * s / 18.0
			pts.append(p + Vector2(cos(a), sin(a)) * r)
		G.poly(self, pts, k[0], 5 * U)
		var inner := PackedVector2Array()
		for s in 19:
			var a := rot + PI * s / 18.0
			inner.append(p + Vector2(cos(a), sin(a)) * r * 0.82)
		draw_colored_polygon(inner, k[1])


func paint() -> void:
	for h in halves:
		draw_fruit(h.p, h.k, h.rot, true)
	for f in fruits:
		if f.live == 1:
			draw_fruit(f.p, f.k, f.rot)
	for tr in trail:
		var a: float = tr.life / 0.18
		draw_line(tr.a, tr.b, Color(1, 1, 1, a), 16 * U * a + 2, true)

files.scripts/micro/splat.gd:
extends "res://scripts/micro.gd"

var mobs: Array = []
var paint_left := 0


func setup() -> void:
	word = "SPLAT!"
	hint = "Paint all the boring blobs!"
	dur = 5.0
	c1 = Color("9aa0b5"); c2 = Color("b0b5c8"); pat = 2
	var n := 3 + lvl
	for i in n:
		mobs.append({p = rnd_in(90), v = Vector2(randf_range(-1, 1), randf_range(-1, 1)).normalized() * (60 + lvl * 60) * U,
			col = G.RAINBOW[i % 6], state = 0, k = 0.0, seed = randf() * 10.0})
	paint_left = n


func tick(dt: float) -> void:
	for m in mobs:
		if m.state == 0:
			m.p += m.v * dt
			if m.p.x < area.position.x + 60 * U or m.p.x > area.end.x - 60 * U:
				m.v.x = -m.v.x
			if m.p.y < area.position.y + 60 * U or m.p.y > area.end.y - 60 * U:
				m.v.y = -m.v.y
			m.p = m.p.clamp(area.position + Vector2(60, 60) * U, area.end - Vector2(60, 60) * U)
		else:
			m.k += dt


func down(p: Vector2, _i: int) -> void:
	if result != 0:
		return
	for m in mobs:
		if m.state == 0 and p.distance_to(m.p) < 85 * U:
			m.state = 1
			paint_left -= 1
			G.play("splat", randf_range(1.0, 1.3))
			fx.burst(m.p, m.col, 20, 500 * U, 12 * U)
			if paint_left == 0:
				win("SO COLORFUL!")
			return


func auto(_dt: float) -> void:
	if int(t * 60) % 15 == 0:
		for m in mobs:
			if m.state == 0:
				down(m.p, 0)
				return


func paint() -> void:
	for m in mobs:
		if m.state == 1:
			draw_colored_polygon(G.splat_pts(m.p, 85 * U, m.seed), Color(m.col, 0.85))
	for m in mobs:
		var p: Vector2 = m.p
		if m.state == 0:
			G.boredom_blob(self, p, 58 * U, t + m.seed, 1 if fmod(t + m.seed, 3.0) < 1.0 else 0)
		else:
			var s := maxf(0.0, 1.0 - m.k * 1.5)
			if s > 0.0:
				G.buddy(self, p - Vector2(0, m.k * 200 * U), 58 * U * s, m.col, t, 0)

