extends "res://scripts/micro.gd"
## BOSS: tickle the Boredom Blob until it laughs itself to pieces.

const LINES := ["HEE HEE!", "STOP IT!", "HA HA HA!", "NOT THERE!", "HOO HOO!", "I'M TICKLISH!", "PFFFT!"]
var c := Vector2.ZERO
var r := 200.0
var meter := 0.0
var need := 24.0
var shake := 0.0
var line := ""
var line_t := 0.0
var feather := Vector2(-999, -999)
var rub := 0.0
var splats: Array = []
var burst_done := false


func setup() -> void:
	word = "TICKLE!"
	hint = "BOSS! Tickle the Boredom Blob!"
	dur = 9.0
	c1 = Color("3b1d6e"); c2 = Color("5a2d9c"); pat = 3
	need = 18.0 + lvl * 7.0
	r = 190 * U
	c = area.get_center()


func tick(dt: float) -> void:
	shake = maxf(0.0, shake - dt * 3.0)
	line_t = maxf(0.0, line_t - dt)
	if result == 0:
		c = area.get_center() + Vector2(sin(t * 1.3 * (0.8 + lvl * 0.3)) * area.size.x * 0.28, sin(t * 2.1) * 50 * U)
	elif result == 1 and not burst_done:
		burst_done = true
		fx.confetti(c, 90, 1200 * U)
		fx.burst(c, G.BLOB, 40, 900 * U, 16 * U)
		G.play("pop1", 0.5)
		G.play("cheer")


func tickle(p: Vector2, amount: float) -> void:
	if result != 0:
		return
	if p.distance_to(c) < r * 1.15:
		meter += amount
		shake = 1.0
		if randf() < 0.25 * amount or line_t <= 0.0:
			line = LINES[randi() % LINES.size()]
			line_t = 0.7
			G.play("giggle", randf_range(0.9, 1.25), -2.0)
		if randf() < 0.5:
			fx.burst(p, G.RAINBOW[randi() % 6], 4, 300 * U, 8 * U)
		if randf() < 0.35 * amount:
			splats.append({a = randf() * TAU, d = randf() * 0.65, s = randf_range(0.12, 0.22), col = G.RAINBOW[randi() % 6], seed = randf() * 9})
		if meter >= need:
			win("YOU BEAT THE BLOB!")


func down(p: Vector2, _i: int) -> void:
	feather = p
	tickle(p, 1.0)


func drag(p: Vector2, _i: int, rel: Vector2) -> void:
	feather = p
	rub += rel.length()
	while rub > 70 * U:
		rub -= 70 * U
		tickle(p, 0.6)


func auto(_dt: float) -> void:
	if int(t * 60) % 7 == 0:
		down(c + Vector2(randf_range(-60, 60), randf_range(-60, 60)) * U, 0)


func paint() -> void:
	# spotlight
	draw_circle(Vector2(c.x, area.end.y), r * 1.6, Color(1, 1, 0.8, 0.08), true, -1.0, true)
	if not (result == 1 and rt > 0.05):
		var sh := Vector2(randf_range(-1, 1), randf_range(-1, 1)) * 14 * U * shake
		var mood := 3 if (shake > 0.2 or result == 1) else 4
		G.boredom_blob(self, c + sh, r, t, mood, splats, 1.0 + shake * 0.08)
		if line_t > 0.0:
			G.speech(self, c + Vector2(r * 0.5, -r * 0.8), c + Vector2(r * 1.1, -r * 1.35), line, int(34 * U), 260 * U)
	# meter
	var mr := Rect2(W * 0.5 - 300 * U, area.position.y - 30 * U, 600 * U, 46 * U)
	G.rrect(self, mr, 23 * U, Color("1c1430"), 6 * U)
	var f := clampf(meter / need, 0.0, 1.0)
	if f > 0.02:
		G.rrect(self, Rect2(mr.position + Vector2(6, 6) * U, Vector2((mr.size.x - 12 * U) * f, mr.size.y - 12 * U)), 17 * U, G.PINK.lerp(G.YELLOW, f), 0)
	G.txt(self, mr.get_center(), "GIGGLE METER", int(28 * U), Color.WHITE, int(6 * U))
	if feather.x > -900:
		var fp := feather + Vector2(30, -30) * U
		var a := -0.8 + sin(t * 18.0) * 0.3
		var d := Vector2(cos(a), sin(a))
		var pts := PackedVector2Array()
		for k in 13:
			var u := k / 12.0
			pts.append(fp + d * (u * 140 * U) + d.orthogonal() * sin(u * PI) * 26 * U)
		for k in 13:
			var u := 1.0 - k / 12.0
			pts.append(fp + d * (u * 140 * U) - d.orthogonal() * sin(u * PI) * 26 * U)
		G.poly(self, pts, G.PINK, 4 * U)
		draw_line(fp - d * 30 * U, fp + d * 140 * U, Color.WHITE, 4 * U, true)

files.scripts/micro/whack.gd:
extends "res://scripts/micro.gd"

var holes: Array = []
var need := 3
var got := 0
var next := 0.3
var ham := Vector2(-999, -999)
var ham_t := 0.0


func setup() -> void:
	word = "BOP!"
	hint = "Bop the moles with the squeaky hammer!"
	dur = 5.5
	c1 = Color("7cf05a"); c2 = Color("94f47a"); pat = 1
	need = 2 + lvl
	for r in 2:
		for c in 3:
			holes.append({p = area.position + Vector2((c + 0.5) * area.size.x / 3.0, (r + 0.62) * area.size.y / 2.0), up = 0.0, timer = 0.0, bopped = 0.0})


func tick(dt: float) -> void:
	ham_t = maxf(0.0, ham_t - dt)
	next -= dt
	if next <= 0.0 and result == 0:
		var free: Array = []
		for h in holes:
			if h.timer <= 0.0 and h.bopped <= 0.0:
				free.append(h)
		if free.size() > 0:
			var h: Dictionary = free[randi() % free.size()]
			h.timer = 1.1 - lvl * 0.15
		next = 0.55 - lvl * 0.08
	for h in holes:
		h.timer -= dt
		h.bopped = maxf(0.0, h.bopped - dt)
		var want := 1.0 if (h.timer > 0.0 or h.bopped > 0.0) else 0.0
		h.up = move_toward(h.up, want, dt * 7.0)


func down(p: Vector2, _i: int) -> void:
	ham = p
	ham_t = 0.25
	if result != 0:
		return
	for h in holes:
		if h.timer > 0.0 and h.up > 0.4 and p.distance_to(h.p - Vector2(0, 60 * U)) < 110 * U:
			h.timer = 0.0
			h.bopped = 0.45
			got += 1
			G.play("squeak", randf_range(0.9, 1.2))
			fx.stars(h.p - Vector2(0, 90 * U), 5, 220 * U)
			if got >= need:
				win("BOP BOP!")
			return
	G.play("bonk", 1.4, -8.0)


func auto(_dt: float) -> void:
	for h in holes:
		if h.timer > 0.0 and h.up > 0.6:
			down(h.p - Vector2(0, 60 * U), 0)
			return


func paint() -> void:
	for h in holes:
		var p: Vector2 = h.p
		G.ellipse(self, p, 105 * U, 34 * U, Color("4a2c1a"), 5 * U)
		var rise: float = h.up * 110 * U
		if rise > 2:
			var m := p + Vector2(0, -rise + 35 * U)
			var body := PackedVector2Array()
			for k in 25:
				var a := PI + PI * k / 24.0
				body.append(m + Vector2(cos(a) * 62 * U, sin(a) * 75 * U))
			body.append(p + Vector2(62 * U, 0))
			body.append(p + Vector2(-62 * U, 0))
			G.poly(self, body, Color("a86b45"), 5 * U)
			G.ellipse(self, m + Vector2(0, -8 * U), 22 * U, 16 * U, Color("ff9fb5"), 3 * U)
			if h.bopped > 0.0:
				G.txt(self, m - Vector2(0, 45 * U), "x  x", int(30 * U), G.NAVY, 0, G.font_bold)
			else:
				G.eyes(self, m - Vector2(0, 45 * U), 13 * U, Vector2(0, 0.4))
			draw_line(m + Vector2(-10, 20) * U, m + Vector2(10, 20) * U, G.NAVY, 4 * U)
		# front lip of the hole
		var lip := PackedVector2Array()
		for k in 17:
			var a := 0.1 + (PI - 0.2) * k / 16.0
			lip.append(p + Vector2(cos(a) * 105 * U, sin(a) * 34 * U))
		draw_polyline(lip, Color("6b8f2a"), 12 * U, true)
	G.txt(self, Vector2(110 * U, 70 * U), "%d/%d" % [got, need], int(46 * U))
	if ham_t > 0.0:
		var a := -0.9 + (1.0 - ham_t / 0.25) * 1.2
		var hand := ham + Vector2(90, 90) * U
		var head := hand + Vector2(cos(a - PI * 0.75), sin(a - PI * 0.75)) * 120 * U
		G.seg(self, hand, head, Color("ffd23f"), 18 * U, G.NAVY, 4 * U)
		G.ellipse(self, head, 50 * U, 34 * U, G.RED, 5 * U, a)

